import{_ as e,o as i,c as t,l as n,t as s,N as o}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse(`{"title":"docker-container-commit | x-cmd man (docker man1) | Create a new image from a container\\\\'s changes","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-container-commit - Create a new image from a container\\\\'s changes","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-container-commit | x-cmd man (docker man1) | Create a new image from a container\\\\'s changes"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-container-commit - Create a new image from a container\\\\'s changes"}]]},"headers":[],"params":{"isMan":true,"man":"docker-container-commit","category":"docker man1","desc":"Create a new image from a container\\\\'s changes"},"relativePath":"docker/man1/docker-container-commit.md","filePath":"docker/man1/docker-container-commit.md"}`),r={name:"docker/man1/docker-container-commit.md"},h={class:"visually-hidden"},c=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-container-commit - Create a new image from a container&#39;s changes</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker container commit [OPTIONS] CONTAINER [REPOSITORY[:TAG]]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Create a new image from an existing container specified by name or container ID. The new image will contain the contents of the container filesystem, <em>excluding</em> any data volumes. Refer to <strong>docker-tag(1)</strong> for more information about valid image and tag names.</p><p>While the <strong>docker commit</strong> command is a convenient way of extending an existing image, you should prefer the use of a Dockerfile and <strong>docker</strong> build for generating images that you intend to share with other people.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h2 id="creating-a-new-image-from-an-existing-container" tabindex="-1">Creating a new image from an existing container <a class="header-anchor" href="#creating-a-new-image-from-an-existing-container" aria-label="Permalink to &quot;Creating a new image from an existing container&quot;">​</a></h2><p>An existing Fedora based container has had Apache installed while running in interactive mode with the bash shell. Apache is also running. To create a new image run <strong>docker ps</strong> to find the container&#39;s ID and then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Added Apache to Fedora base image&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -a=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A D Ministrator&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 98bd7fc99854</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fedora/fedora_httpd:20</span></span></code></pre></div><p>Note that only a-z0-9-_. are allowed when naming images from an existing container.</p><h2 id="apply-specified-dockerfile-instructions-while-committing-the-image" tabindex="-1">Apply specified Dockerfile instructions while committing the image <a class="header-anchor" href="#apply-specified-dockerfile-instructions-while-committing-the-image" aria-label="Permalink to &quot;Apply specified Dockerfile instructions while committing the image&quot;">​</a></h2><p>If an existing container was created without the DEBUG environment variable set to &quot;true&quot;, you can create a new image based on that container by first getting the container&#39;s ID with <strong>docker ps</strong> and then running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ENV DEBUG=true&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 98bd7fc99854</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug-image</span></span></code></pre></div><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-a</strong>, <strong>--author</strong>=&quot;&quot; Author (e.g., &quot;John Hannibal Smith <a href="mailto:hannibal@a-team.com" target="_blank" rel="noreferrer">hannibal@a-team.com</a> ⟨<a href="mailto:hannibal@a-team.com" target="_blank" rel="noreferrer">mailto:hannibal@a-team.com</a>⟩&quot;)</p><p><strong>-c</strong>, <strong>--change</strong>= Apply Dockerfile instruction to the created image</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for commit</p><p><strong>-m</strong>, <strong>--message</strong>=&quot;&quot; Commit message</p><p><strong>-p</strong>, <strong>--pause</strong>[=true] Pause container during commit</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-container(1)</strong></p>',23);function l(a,m,d,g,p,k){return i(),t("div",null,[n("h1",h,s(a.$params.man),1),c])}const F=e(r,[["render",l]]);export{f as __pageData,F as default};
